/**
 * cc-proxy 설정 — `~/.config/cc-proxy/config.json`.
 *
 * Claude Code 별칭(haiku/sonnet/opus/fable)마다 프록시 대상 체인을 둔다. 체인 앞에서부터 시도하고,
 * 모두 실패하면 원래 Claude 모델(Anthropic 직행)로 간다. 체인이 비면 그 별칭은 그대로 Anthropic이다.
 * `enabled: false`면 모든 요청이 그대로 Anthropic으로 간다(Claude Code는 세션 중에도 프록시를 거친다).
 */
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { homedir } from "node:os";

export const ALIASES = ["haiku", "sonnet", "opus", "fable"] as const;
export type Alias = (typeof ALIASES)[number];
/** `off` = `thinking: {type: "disabled"}`. pi 카탈로그에 off가 없는 모델이면 low로 보낸다(`levels.ts`). */
export const EFFORTS = ["off", "low", "medium", "high", "xhigh", "max"] as const;
export type Effort = (typeof EFFORTS)[number];

/** 체인 한 칸: `provider/model`. `effort`가 있으면 Claude Code가 보낸 effort 대신 이 값을 보낸다. */
export type Target = { model: string; effort?: Effort };
/** `common: false`면 그 별칭은 공통 층(`levels.ts` `commonText`)을 붙이지 않는다. 기본은 붙인다. */
export type Route = { chain: Target[]; common?: false };
export type Config = {
	enabled: boolean;
	routes: Record<Alias, Route>;
	/** 429·5xx·연결·인증 실패 뒤 그 대상을 건너뛰는 시간. */
	cooldownSeconds: number;
	/** true(기본)면 서브에이전트 요청(`x-claude-code-agent-id` 헤더)만 체인을 탄다. 메인 대화와 보조 호출은
	 *  모델이 무엇이든 Anthropic 직행이다(`proxiable`). */
	subagentsOnly: boolean;
};

export const PORT = Number(process.env.CC_PROXY_PORT ?? 45870);

/** Claude Code 2.1.322는 서브에이전트의 API 요청에만 `x-claude-code-agent-id`를 붙인다(메인에는 없음, 261111 실측). */
export const AGENT_HEADER = "x-claude-code-agent-id";

/** 체인을 탈 요청인가: `subagentsOnly`면 서브에이전트 요청만. */
export function proxiable(config: Config, headers: Headers): boolean {
	return !config.subagentsOnly || headers.has(AGENT_HEADER);
}

export const DEFAULT_CONFIG: Config = {
	enabled: true,
	routes: {
		haiku: { chain: [{ model: "opencode-go/deepseek-v4.1-flash" }] },
		sonnet: { chain: [{ model: "xai/grok-4.7" }] },
		opus: { chain: [] },
		fable: { chain: [] },
	},
	cooldownSeconds: 60,
	subagentsOnly: true,
};

export function configDir(): string {
	return process.env.CC_PROXY_CONFIG_DIR ?? join(homedir(), ".config", "cc-proxy");
}

/** Claude 모델 ID(`claude-haiku-5-5`, `claude-opus-5-5[1m]`)의 별칭. Claude가 아니면 null. */
export function aliasOf(model: unknown): Alias | null {
	if (typeof model !== "string") return null;
	const match = /^claude-(haiku|sonnet|opus|fable)\b/.exec(model.toLowerCase());
	return (match?.[1] as Alias | undefined) ?? null;
}

/** `provider/model` → 둘로. 형식이 틀리면 null. */
export function splitTarget(model: string): { provider: string; id: string } | null {
	const slash = model.indexOf("/");
	if (slash <= 0 || slash === model.length - 1) return null;
	return { provider: model.slice(0, slash), id: model.slice(slash + 1) };
}

/** 검증하고 빠진 칸은 기본값으로 채운다. 틀리면 이유를 던진다. */
export function validate(input: unknown, providers: readonly string[]): Config {
	if (!input || typeof input !== "object") throw new Error("config must be an object");
	const raw = input as Partial<Config> & { routes?: Partial<Record<string, Partial<Route>>> };
	const routes = {} as Record<Alias, Route>;
	for (const alias of ALIASES) {
		const chain = raw.routes?.[alias]?.chain ?? DEFAULT_CONFIG.routes[alias].chain;
		if (!Array.isArray(chain)) throw new Error(`${alias}: chain must be a list`);
		if (chain.length > 8) throw new Error(`${alias}: at most 8 targets`);
		const seen = new Set<string>();
		const common = raw.routes?.[alias]?.common;
		if (common !== undefined && typeof common !== "boolean") throw new Error(`${alias}: common is true/false`);
		routes[alias] = {
			...(common === false ? { common: false as const } : {}),
			chain: chain.map((target) => {
				if (!target || typeof target.model !== "string") throw new Error(`${alias}: target needs a model`);
				const split = splitTarget(target.model);
				if (!split) throw new Error(`${alias}: ${target.model} is not provider/model`);
				if (!providers.includes(split.provider)) {
					throw new Error(`${alias}: provider ${split.provider} is not supported (${providers.join(", ")})`);
				}
				if (seen.has(target.model)) throw new Error(`${alias}: ${target.model} is listed twice`);
				seen.add(target.model);
				if (target.effort !== undefined && !EFFORTS.includes(target.effort)) {
					throw new Error(`${alias}: effort is ${EFFORTS.join("/")}`);
				}
				return target.effort ? { model: target.model, effort: target.effort } : { model: target.model };
			}),
		};
	}
	const cooldownSeconds = raw.cooldownSeconds ?? DEFAULT_CONFIG.cooldownSeconds;
	if (!(Number.isFinite(cooldownSeconds) && cooldownSeconds >= 0 && cooldownSeconds <= 3600)) {
		throw new Error("cooldownSeconds is 0–3600");
	}
	const subagentsOnly = raw.subagentsOnly ?? DEFAULT_CONFIG.subagentsOnly;
	if (typeof subagentsOnly !== "boolean") throw new Error("subagentsOnly is true/false");
	return { enabled: raw.enabled ?? DEFAULT_CONFIG.enabled, routes, cooldownSeconds, subagentsOnly };
}

/** 파일 버전: 저장할 때 읽은 버전과 다르면(그 사이 손으로 고쳤으면) 거절한다. */
export function versionOf(path: string): string {
	try {
		const stat = statSync(path);
		return `${stat.mtimeMs}-${stat.size}`;
	} catch {
		return "missing";
	}
}

export function configPath(): string {
	return join(configDir(), "config.json");
}

export function readConfig(providers: readonly string[]): { config: Config; version: string; error?: string } {
	const path = configPath();
	const version = versionOf(path);
	if (!existsSync(path)) return { config: DEFAULT_CONFIG, version };
	try {
		return { config: validate(JSON.parse(readFileSync(path, "utf8")), providers), version };
	} catch (cause) {
		return { config: DEFAULT_CONFIG, version, error: cause instanceof Error ? cause.message : String(cause) };
	}
}

export function writeConfig(config: Config): string {
	const path = configPath();
	mkdirSync(dirname(path), { recursive: true });
	const tmp = `${path}.${process.pid}.tmp`;
	writeFileSync(tmp, `${JSON.stringify(config, null, "\t")}\n`);
	renameSync(tmp, path);
	return versionOf(path);
}

#!/usr/bin/env bun
/**
 * cc-proxy — Claude Code 별칭(haiku/sonnet/…)을 다른 업체 모델로 보내는 로컬 Anthropic 프록시.
 *
 *   cc-proxy serve        systemd(`cc-proxy.service`)가 띄운다
 *   cc-proxy status       켜짐 여부, 오늘 호출 수, 쿨다운
 *   cc-proxy on | off     라우팅 켜기/끄기(꺼도 Claude Code 요청은 그대로 Anthropic으로 통과)
 */
import { PORT } from "./config.ts";
import { serve } from "./server.ts";

const base = `http://127.0.0.1:${PORT}/_proxy`;

async function call(path: string, init?: RequestInit) {
	const response = await fetch(base + path, { ...init, headers: { "content-type": "application/json" } });
	if (!response.ok) throw new Error(`${path}: ${response.status} ${await response.text()}`);
	return response.json() as Promise<Record<string, any>>;
}

const [command = "status"] = process.argv.slice(2);
switch (command) {
	case "serve":
		serve();
		break;
	case "on":
	case "off": {
		await call("/enabled", { method: "POST", body: JSON.stringify({ enabled: command === "on" }) });
		console.log(`cc-proxy ${command}`);
		break;
	}
	case "status": {
		try {
			const stats = await call("/stats");
			const day = stats.day.bucket;
			console.log(`cc-proxy ${stats.enabled ? "on" : "off"} · today ${day.proxied} proxied · ${day.native} native · ${day.fallbacks} fallbacks · ${day.errors} errors`);
			for (const [target, counter] of Object.entries<any>(day.targets)) {
				console.log(`  ${target}: ${counter.calls} calls · ${counter.errors} errors · ${counter.input}/${counter.output} tok`);
			}
			for (const cooling of stats.cooldowns) console.log(`  cooling ${cooling.target} until ${new Date(cooling.until).toLocaleTimeString()}`);
		} catch {
			console.log("cc-proxy is not running (systemctl --user start cc-proxy)");
			process.exitCode = 1;
		}
		break;
	}
	default:
		console.error("usage: cc-proxy serve | status | on | off");
		process.exitCode = 2;
}

/**
 * 프록시가 보낼 수 있는 업체와 그 자격 증명.
 *
 * 키는 pi의 `~/.pi/agent/auth.json`을 그대로 쓴다(pi와 같은 계정·할당량). OAuth 토큰이 만료되면
 * pi와 같은 방식(`proper-lockfile`: `auth.json.lock` 디렉터리, 10초 지나면 stale)으로 잠그고 갱신해
 * 다시 쓴다. 회전된 refresh 토큰을 pi와 엇갈려 잃지 않기 위해서다.
 *
 * 업체 정의는 표 하나다. 라우팅 로직은 업체 이름으로 갈라지지 않고, 업체마다 다른 것은
 * 주소·인증 헤더·추가 헤더뿐이다.
 */
import { mkdirSync, readFileSync, renameSync, rmdirSync, statSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export type Credential =
	| { type: "api_key"; key: string }
	| { type: "oauth"; access: string; refresh: string; expires: number; [extra: string]: unknown };

type OAuthRefresh = { tokenUrl: string; clientId: string };

export type Provider = {
	/** `/v1/messages`를 붙일 Anthropic 호환 주소(끝에 `/v1` 없음). */
	baseUrl: string;
	/** 자격 증명을 요청 헤더로. */
	auth: (credential: Credential) => Record<string, string>;
	/** 세션 ID가 필요한 업체의 추가 헤더. */
	headers?: (sessionId: string) => Record<string, string>;
	refresh?: OAuthRefresh;
};

const bearerOrKey = (credential: Credential): Record<string, string> =>
	credential.type === "api_key" ? { "x-api-key": credential.key } : { authorization: `Bearer ${credential.access}` };

export const PROVIDERS: Record<string, Provider> = {
	// OpenCode Go: 세션 헤더가 없으면 MissingSessionID로 거절한다(261111 실측).
	"opencode-go": {
		baseUrl: "https://opencode.ai/zen/go",
		auth: bearerOrKey,
		headers: (sessionId) => ({ "x-opencode-session": sessionId, "x-opencode-client": "claude-code" }),
	},
	// xAI: pi의 SuperGrok OAuth(device code) 토큰이 api.x.ai/v1/messages에 그대로 통한다.
	xai: {
		baseUrl: "https://api.x.ai",
		auth: bearerOrKey,
		refresh: { tokenUrl: "https://auth.x.ai/oauth2/token", clientId: "b1a00492-073a-47ea-816f-4c329264a828" },
	},
};

export const PROVIDER_NAMES = Object.keys(PROVIDERS);

export function authPath(): string {
	return process.env.CC_PROXY_AUTH_FILE ?? join(homedir(), ".pi", "agent", "auth.json");
}

let cache: { mtime: number; data: Record<string, Credential> } | null = null;

function readAuth(): Record<string, Credential> {
	const path = authPath();
	const mtime = statSync(path).mtimeMs;
	if (cache?.mtime === mtime) return cache.data;
	const data = JSON.parse(readFileSync(path, "utf8")) as Record<string, Credential>;
	cache = { mtime, data };
	return data;
}

const STALE_MS = 10_000;
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

/** pi(`proper-lockfile`)와 같은 잠금. */
async function withAuthLock<T>(fn: () => Promise<T>): Promise<T> {
	const lock = `${authPath()}.lock`;
	for (let attempt = 0; ; attempt += 1) {
		try {
			mkdirSync(lock);
			break;
		} catch (cause) {
			if ((cause as NodeJS.ErrnoException).code !== "EEXIST") throw cause;
			try {
				if (Date.now() - statSync(lock).mtimeMs > STALE_MS) rmdirSync(lock);
			} catch {
				// 그 사이 풀렸다.
			}
			if (attempt > 100) throw new Error("auth.json is locked");
			await sleep(50);
		}
	}
	try {
		return await fn();
	} finally {
		try {
			rmdirSync(lock);
		} catch {
			// 이미 없다.
		}
	}
}

const refreshing = new Map<string, Promise<Credential>>();

async function refreshOAuth(name: string, spec: OAuthRefresh): Promise<Credential> {
	return withAuthLock(async () => {
		cache = null;
		const all = readAuth();
		const current = all[name];
		if (current?.type !== "oauth") throw new Error(`${name}: no OAuth login in pi`);
		// pi가 먼저 갱신했다.
		if (current.expires > Date.now()) return current;
		const response = await fetch(spec.tokenUrl, {
			method: "POST",
			headers: { "content-type": "application/x-www-form-urlencoded", accept: "application/json" },
			body: new URLSearchParams({ grant_type: "refresh_token", client_id: spec.clientId, refresh_token: current.refresh }),
			signal: AbortSignal.timeout(20_000),
		});
		if (!response.ok) throw new Error(`${name}: token refresh failed (${response.status}); run pi /login`);
		const body = (await response.json()) as { access_token: string; refresh_token?: string; expires_in?: number };
		const next: Credential = {
			...current,
			access: body.access_token,
			refresh: body.refresh_token ?? current.refresh,
			// pi와 같이 5분 일찍 만료로 본다.
			expires: Date.now() + (body.expires_in ?? 3600) * 1000 - 5 * 60_000,
		};
		const path = authPath();
		const tmp = `${path}.cc-proxy.tmp`;
		writeFileSync(tmp, JSON.stringify({ ...all, [name]: next }, null, 2), { mode: 0o600 });
		renameSync(tmp, path);
		cache = null;
		return next;
	});
}

/** 업체의 유효한 자격 증명. 없으면 이유를 던진다. */
export async function credentialFor(name: string): Promise<Credential> {
	const provider = PROVIDERS[name];
	if (!provider) throw new Error(`unknown provider ${name}`);
	const credential = readAuth()[name];
	if (!credential) throw new Error(`${name}: not logged in to pi`);
	if (credential.type !== "oauth" || credential.expires > Date.now()) return credential;
	if (!provider.refresh) throw new Error(`${name}: OAuth token expired`);
	let pending = refreshing.get(name);
	if (!pending) {
		pending = refreshOAuth(name, provider.refresh).finally(() => refreshing.delete(name));
		refreshing.set(name, pending);
	}
	return pending;
}

/** 이 업체에 pi 로그인이 있는가(GUI에서 고를 수 있는 업체 표시용). */
export function loggedIn(name: string): boolean {
	try {
		return Boolean(readAuth()[name]);
	} catch {
		return false;
	}
}

/**
 * 호출 집계 — 전체(오늘 · 누적)와 Claude Code 세션별(`x-claude-code-session-id`).
 *
 * 한 번의 `/v1/messages` 요청은 결과 하나로 센다: 어느 대상이 받았는지(`provider/model` 또는
 * `native/<claude id>`), 앞 대상이 실패해 넘어간 횟수(fallback), 토큰. `~/.local/state/cc-proxy/stats.json`에
 * 몇 초마다 저장해 재시작해도 남는다. 세션은 최근 200개만 둔다.
 */
import { mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

export type Counter = { calls: number; errors: number; fallbacks: number; input: number; output: number; cacheRead: number };
export type Bucket = {
	/** 프록시 대상(`native/…` 아닌 것)이 받은 요청 수. */
	proxied: number;
	/** Anthropic이 받은 요청 수(체인 없는 별칭, 꺼짐, 마지막 fallback). */
	native: number;
	fallbacks: number;
	errors: number;
	/** 받은 대상별. */
	targets: Record<string, Counter>;
	/** 별칭별(haiku/sonnet/…, Claude가 아닌 모델은 other). */
	aliases: Record<string, { proxied: number; native: number }>;
	updatedAt: number;
};
export type Stats = {
	total: Bucket;
	day: { date: string; bucket: Bucket };
	sessions: Record<string, Bucket>;
	/** 실패해서 쿨다운 중인 대상과 끝나는 시각, 마지막 실패. */
	recentFailures: { at: number; target: string; status: number | string; message: string }[];
};

export const emptyBucket = (): Bucket => ({
	proxied: 0,
	native: 0,
	fallbacks: 0,
	errors: 0,
	targets: {},
	aliases: {},
	updatedAt: 0,
});
const emptyCounter = (): Counter => ({ calls: 0, errors: 0, fallbacks: 0, input: 0, output: 0, cacheRead: 0 });
const today = () => new Date().toLocaleDateString("sv-SE");

export function statsPath(): string {
	return process.env.CC_PROXY_STATS_FILE ?? join(homedir(), ".local", "state", "cc-proxy", "stats.json");
}

export function load(): Stats {
	try {
		const parsed = JSON.parse(readFileSync(statsPath(), "utf8")) as Stats;
		if (parsed.total && parsed.day && parsed.sessions) return { ...parsed, recentFailures: parsed.recentFailures ?? [] };
	} catch {
		// 처음이거나 깨졌다: 새로 센다.
	}
	return { total: emptyBucket(), day: { date: today(), bucket: emptyBucket() }, sessions: {}, recentFailures: [] };
}

export type Outcome = {
	session?: string;
	alias: string;
	/** 받은 대상. 모두 실패했으면 undefined. */
	target?: string;
	/** 받기 전 실패한 대상 수. */
	fallbacks: number;
	usage?: { input: number; output: number; cacheRead: number };
};

function apply(bucket: Bucket, outcome: Outcome) {
	const native = outcome.target?.startsWith("native/") ?? false;
	const alias = (bucket.aliases[outcome.alias] ??= { proxied: 0, native: 0 });
	bucket.fallbacks += outcome.fallbacks;
	bucket.updatedAt = Date.now();
	if (!outcome.target) {
		bucket.errors += 1;
		return;
	}
	if (native) {
		bucket.native += 1;
		alias.native += 1;
	} else {
		bucket.proxied += 1;
		alias.proxied += 1;
	}
	const counter = (bucket.targets[outcome.target] ??= emptyCounter());
	counter.calls += 1;
	counter.fallbacks += outcome.fallbacks;
	counter.input += outcome.usage?.input ?? 0;
	counter.output += outcome.usage?.output ?? 0;
	counter.cacheRead += outcome.usage?.cacheRead ?? 0;
}

export function record(stats: Stats, outcome: Outcome) {
	if (stats.day.date !== today()) stats.day = { date: today(), bucket: emptyBucket() };
	apply(stats.total, outcome);
	apply(stats.day.bucket, outcome);
	if (outcome.session) {
		apply((stats.sessions[outcome.session] ??= emptyBucket()), outcome);
		const ids = Object.keys(stats.sessions);
		if (ids.length > 200) {
			ids.sort((a, b) => stats.sessions[a]!.updatedAt - stats.sessions[b]!.updatedAt);
			for (const id of ids.slice(0, ids.length - 200)) delete stats.sessions[id];
		}
	}
}

/** 대상이 실패했다: 그 대상 카운터의 errors와 최근 실패 목록. */
export function recordFailure(stats: Stats, target: string, status: number | string, message: string) {
	for (const bucket of [stats.total, stats.day.bucket]) (bucket.targets[target] ??= emptyCounter()).errors += 1;
	stats.recentFailures = [{ at: Date.now(), target, status, message: message.slice(0, 300) }, ...stats.recentFailures].slice(0, 20);
}

export function save(stats: Stats) {
	const path = statsPath();
	mkdirSync(dirname(path), { recursive: true });
	const tmp = `${path}.tmp`;
	writeFileSync(tmp, JSON.stringify(stats));
	renameSync(tmp, path);
}

